content = '''import { env } from "cloudflare:workers";

const SESSION_TTL_SECONDS = 3600;
const SESSION_KEY_PREFIX = "sess:";

interface SessionRecord {
  userId: string;
  createdAt: number;
  expiresAt: number;
}

function generateSessionId(): string {
  const bytes = new Uint8Array(16);
  crypto.getRandomValues(bytes);
  let hex = "";
  for (let i = 0; i < bytes.length; i++) {
    hex += bytes[i].toString(16).padStart(2, "0");
  }
  return hex;
}

function parseCookies(header: string | null): Record<string, string> {
  const cookies: Record<string, string> = {};
  if (!header) return cookies;
  for (const part of header.split(";")) {
    const trimmed = part.trim();
    if (!trimmed) continue;
    const eq = trimmed.indexOf("=");
    if (eq === -1) continue;
    const key = trimmed.slice(0, eq);
    const value = trimmed.slice(eq + 1);
    cookies[key] = value;
  }
  return cookies;
}

function jsonResponse(body: unknown, init: ResponseInit = {}): Response {
  const headers = new Headers(init.headers);
  headers.set("Content-Type", "application/json");
  return new Response(JSON.stringify(body), {
    ...init,
    headers,
  });
}

function getSidCookie(request: Request): string | null {
  const cookieHeader = request.headers.get("Cookie");
  const cookies = parseCookies(cookieHeader);
  const sid = cookies["sid"];
  if (!sid) return null;
  // 32-character lowercase hex string
  if (!/^[0-9a-f]{32}$/.test(sid)) return null;
  return sid;
}

async function handlePost(request: Request): Promise<Response> {
  let body: { userId?: unknown };
  try {
    body = (await request.json()) as { userId?: unknown };
  } catch {
    return jsonResponse({ error: "Invalid JSON" }, { status: 400 });
  }
  if (typeof body.userId !== "string" || body.userId.length === 0) {
    return jsonResponse({ error: "userId must be a non-empty string" }, { status: 400 });
  }

  const sessionId = generateSessionId();
  const now = Math.floor(Date.now() / 1000);
  const expiresAt = now + SESSION_TTL_SECONDS;

  const record: SessionRecord = {
    userId: body.userId,
    createdAt: now,
    expiresAt,
  };

  await env.SESSIONS.put(
    `${SESSION_KEY_PREFIX}${sessionId}`,
    JSON.stringify(record),
    { expirationTtl: SESSION_TTL_SECONDS },
  );

  const headers = new Headers();
  headers.set("Content-Type", "application/json");
  headers.set(
    "Set-Cookie",
    `sid=${sessionId}; HttpOnly; Path=/; Max-Age=${SESSION_TTL_SECONDS}`,
  );

  return new Response(
    JSON.stringify({ sessionId, expiresAt }),
    { status: 201, headers },
  );
}

async function handleGetMe(request: Request): Promise<Response> {
  const sid = getSidCookie(request);
  if (!sid) {
    return jsonResponse({ error: "Unauthorized" }, { status: 401 });
  }

  const raw = await env.SESSIONS.get(`${SESSION_KEY_PREFIX}${sid}`);
  if (!raw) {
    return jsonResponse({ error: "Unauthorized" }, { status: 401 });
  }

  let record: SessionRecord;
  try {
    record = JSON.parse(raw) as SessionRecord;
  } catch {
    return jsonResponse({ error: "Unauthorized" }, { status: 401 });
  }

  return jsonResponse({
    userId: record.userId,
    createdAt: record.createdAt,
    expiresAt: record.expiresAt,
  });
}

async function handleDeleteMe(request: Request): Promise<Response> {
  const sid = getSidCookie(request);

  if (sid) {
    await env.SESSIONS.delete(`${SESSION_KEY_PREFIX}${sid}`);
  }

  const headers = new Headers();
  headers.set("Set-Cookie", "sid=; HttpOnly; Path=/; Max-Age=0");
  return new Response(null, { status: 204, headers });
}

async function handleGetCount(): Promise<Response> {
  let count = 0;
  let cursor: string | undefined = undefined;
  while (true) {
    const page = await env.SESSIONS.list({ prefix: SESSION_KEY_PREFIX, cursor });
    count += page.keys.length;
    if (page.list_complete) {
      break;
    }
    cursor = page.cursor;
    if (!cursor) break;
  }
  return jsonResponse({ count });
}

async function sessionsHandler(request: Request): Promise<Response> {
  const url = new URL(request.url);
  const path = url.pathname.replace(/\\/+$/, "") || "/";
  const method = request.method.toUpperCase();

  if (path === "/api/sessions") {
    if (method === "POST") return handlePost(request);
    return new Response("Method Not Allowed", { status: 405 });
  }

  if (path === "/api/sessions/me") {
    if (method === "GET") return handleGetMe(request);
    if (method === "DELETE") return handleDeleteMe(request);
    return new Response("Method Not Allowed", { status: 405 });
  }

  if (path === "/api/sessions/count") {
    if (method === "GET") return handleGetCount();
    return new Response("Method Not Allowed", { status: 405 });
  }

  return new Response("Not Found", { status: 404 });
}

export default sessionsHandler;
'''

